import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>يصل جدار طويل من النص في بريد أو رسالة محادثة أو رد API، وفي مكان ما داخله توجد صورة. النص سلسلة Base64، والصورة تنتظر أن تُفك.</p>\n<p>فك الترميز يحوّل تلك السلسلة إلى ملف الصورة الأصلي. إنه عكس الترميز، وبنفس الدقة: البايتات الخارجة هي نفس البايتات الداخلة.</p>\n<p>يشرح هذا الدليل كيف يعمل <a href=\"/ar/tahwil-base64-ila-sura/\">مفكك Base64 إلى صورة</a> في CompressMyPic، وما الذي يقبله، وما الذي يعرضه، وكيف تحصل على ملف صورة قابل للاستخدام من أي سلسلة Base64.</p>\n<h2 id=\"what-is-base64-to-image\">ما هو مفكك Base64 إلى صورة؟</h2>\n<p>مفكك Base64 إلى صورة يأخذ سلسلة نصية ويحوّلها إلى ملف صورة يمكنك رؤيته وتنزيله واستخدامه. إنه يعكس عملية الترميز بدقة كاملة.</p>\n<p>تلصق السلسلة في الأداة، فتظهر الصورة المفكوكة كمعاينة مع أبعادها وحجم ملفها. ثم تنزّلها بالصيغة الأصلية أو تحوّلها إلى PNG. وتقبل الأداة السلاسل مع بادئة data:image أو بدونها.</p>\n<h2 id=\"how-decoding-works\">كيف يعمل فك ترميز Base64</h2>\n<p>الفك يقرأ السلسلة أربعة أحرف في كل مرة. كل مجموعة من أربعة أحرف تحمل 24 بت من البيانات، يقسمها المفكك إلى ثلاثة بايتات من الملف الأصلي.</p>\n<p>علامات يساوي في نهاية السلسلة هي حشو يخبر المفكك بعدد بايتات المجموعة الأخيرة. علامة واحدة تعني بايتين، وعلامتان تعنيان بايتًا واحدًا. والعملية دقيقة: السلسلة المرمّزة صحيحًا تُفك إلى ملف مطابق بايتًا ببايت.</p>\n<h2 id=\"with-and-without-prefix\">السلاسل مع بادئة data:image وبدونها</h2>\n<p>سلاسل صور Base64 تأتي في شكلين. رابط البيانات الكامل يبدأ بـdata:image/png;base64 متبوعًا بالسلسلة، بينما السلسلة الخام هي الأحرف المرمّزة فقط.</p>\n<p>المفكك يقبل الشكلين. الصق رابط بيانات كاملًا من صفحة ويب، أو الصق سلسلة خامًا من JSON، وستكتشف الأداة الشكل الذي استلمته. وهذا مهم لأن الشكلين يظهران في أماكن مختلفة.</p>\n<h2 id=\"url-safe-and-line-breaks\">المتغيرات الآمنة للروابط وفواصل الأسطر</h2>\n<p>Base64 القياسي يستخدم زائد وشرطة مائلة، ولهما معانٍ خاصة داخل الروابط. المتغير الآمن للروابط يستبدلهما بشرطة وشرطة سفلية لتستطيع السلسلة السفر في رابط.</p>\n<p>المفكك يفهم الأبجديتين. كما يتسامح مع فواصل الأسطر التي تُدخلها عملاء البريد والمستندات عند لف السلاسل الطويلة، ومع المسافات الزائدة، فالسلسلة الملفوفة أو المقتبسة تُفك صحيحًا.</p>\n<h2 id=\"auto-decode-on-paste\">الفك التلقائي عند اللصق</h2>\n<p>لا تحتاج إلى النقر على أي زر للفك. لصق سلسلة Base64 في الأداة يفعّل الفك تلقائيًا، وتظهر المعاينة في لحظات.</p>\n<p>الفك التلقائي راحة صغيرة مهمة عند العمل مع سلاسل كثيرة. الصق وراجع المعاينة ونزّل ثم الصق التالية دون نقرة إضافية لكل صورة. وإذا كانت السلسلة طويلة جدًا، قد يستغرق الفك ثانية أو ثانيتين.</p>\n<h2 id=\"checkerboard-preview\">معاينة المربعات</h2>\n<p>تظهر الصورة المفكوكة فوق خلفية مربعات، وهي الطريقة القياسية لعرض الشفافية. المربعات الرمادية والبيضاء خلف الصورة تحدد المناطق الشفافة فيها.</p>\n<p>خلفية المربعات مفيدة خصوصًا للأيقونات والشعارات. PNG ذو الخلفية الشفافة يبدو مطابقًا لذي الخلفية البيضاء على صفحة بيضاء عادية، لكن خلفية المربعات تكشف الفرق. واستخدم المعاينة لتقرر صيغة التنزيل.</p>\n<h2 id=\"metrics-shown\">المقاييس: الأبعاد والصيغة والحجم</h2>\n<p>بجانب المعاينة، تعرض الأداة أبعاد الصورة المفكوكة بالبكسل وصيغتها المكتشفة وحجم الملف الثنائي بالكيلوبايت أو الميغابايت.</p>\n<p>الحجم الثنائي أصغر دائمًا من نص Base64 الذي لصقته بنحو الربع. والأبعاد تخبرك هل تصلح الصورة لغرضك: أيقونة 64 في 64 مفكوكة من سلسلة هي أيقونة مفضلة لا صورة رئيسية، ولا صيغة تنزيل تغيّر ذلك.</p>\n<h2 id=\"download-formats\">صيغ التنزيل: الأصلية وPNG وJPG وWebP</h2>\n<p>بعد فك السلسلة، تختار صيغة التنزيل. الأصلية تحافظ على الملف تمامًا كما رُمّز، بايتًا ببايت، وهي الخيار الآمن عندما لا تكون متأكدًا.</p>\n<p>PNG هو الخيار الصحيح للصور ذات الشفافية أو الحواف الحادة، لأنه يحافظ على البكسلات بدقة ويبقي قناة ألفا سليمة. وJPG للصور الفوتوغرافية التي تحتاج أن تكون صغيرة، وWebP هو الوسط الحديث: أصغر من PNG لمعظم الصور مع دعم الشفافية.</p>\n<h2 id=\"transparency-and-jpg\">الشفافية وفخ JPG</h2>\n<p>الشفافية أسهل ما يُفقد عند الفك. PNG ذو الخلفية الشفافة يُنزَّل كـJPG فتُملأ مناطقه الشفافة، غالبًا بالأبيض أو الأسود.</p>\n<p>الملء دائم. بعد حفظ الصورة كـJPG تختفي معلومات الشفافية، وتحويلها إلى PNG لن يعيدها. راجع دائمًا معاينة المربعات قبل اختيار JPG، وعند الشك نزّل كأصلية.</p>\n<h2 id=\"animated-gif-and-svg\">صور GIF المتحركة وSVG المتجهة</h2>\n<p>صور GIF المتحركة تنجو من الفك سليمة عند تنزيلها كأصلية. الإطارات والتوقيت وإعدادات التكرار جزء من البيانات الثنائية، ويفكها المفكك كما هي.</p>\n<p>تحويل GIF متحرك إلى PNG أو JPG يدمر الحركة، لأن هاتين الصيغتين تحفظان إطارًا ثابتًا واحدًا. أما ملفات SVG فهي متجهات تُفك إلى نفس كود SVG الذي رُمّز، ويمكنك أيضًا تحويل SVG مفكوك إلى PNG نقطي.</p>\n<h2 id=\"error-handling\">ماذا يحدث مع سلسلة تالفة</h2>\n<p>سلسلة Base64 التالفة أو التي ليست صورة تفشل برسالة خطأ واضحة. الأداة لا تخمّن ولا تنتج ملف صورة جزئيًا أو مكسورًا.</p>\n<p>الأسباب الشائعة تشمل سلسلة قُطعت عند النسخ، أو أحرف غيّرها تطبيق محادثة أو محرر مستندات، أو سلسلة لم تكن صورة أبدًا. عند رؤية الخطأ، راجع السلسلة أولًا وقارن طولها بالأصل إن أمكن، وابحث عن أحرف مفقودة في البداية أو النهاية.</p>\n<h2 id=\"svg-without-base64-marker\">SVG دون علامة base64</h2>\n<p>بعض روابط بيانات SVG ليست Base64 إطلاقًا. تحمل كود SVG مباشرة كنص مرمّز في الرابط، وتبدو مثل data:image/svg+xml دون علامة الفاصلة المنقوطة base64.</p>\n<p>لصق تلك السلسلة في المفكك ينتج خطأ ترميز، لأن الأداة تتوقع أحرف Base64 وتجد أقواسًا وعلامات اقتباس. والحل هو التعرف على الشكل: إذا كانت السلسلة تحتوي على وسوم SVG مقروءة مثل svg وpath، فهي رابط بيانات SVG عادي لا يحتاج فكًا.</p>\n<h2 id=\"privacy-local-processing\">الخصوصية: الفك يحدث في متصفحك</h2>\n<p>سلاسل Base64 تحمل غالبًا مواد حساسة: ردود API داخلية أو أيقونات خاصة أو رموز QR أو مخططات سرية. لصق هذه السلاسل في أداة على الإنترنت ترفعها سيكون خطرًا.</p>\n<p>هذا المفكك يعمل محليًا. تُلصق السلسلة في متصفحك وتُفك على جهازك، والصورة الناتجة لا تغادر حاسوبك أبدًا. وهذا يعني أيضًا أن الأداة تعمل دون اتصال بعد تحميل الصفحة.</p>\n<h2 id=\"decoding-from-documents-and-qr\">كيف تفك صورًا وجدتها في مستندات</h2>\n<p>سلاسل Base64 تختبئ في أماكن لا تتوقعها. مستندات Word وPDF وملفات التصميم تحفظ أحيانًا صورًا مضمّنة كـBase64 داخل هياكل XML أو JSON.</p>\n<p>عندما تجد ذلك المقطع، انسخ السلسلة بعناية بطولها الكامل. صيغ المستندات تقسم السلاسل الطويلة غالبًا إلى أسطر عدة، فتأكد من عدم فقدان أي جزء. ورموز QR حالة مختلفة: معظمها يحمل رابطًا لا صورة.</p>\n<h2 id=\"how-to-use-the-tool\">كيف تستخدم مفكك Base64 إلى صورة</h2>\n<p>افتح <a href=\"/ar/tahwil-base64-ila-sura/\">مفكك Base64 إلى صورة</a> والصق سلسلتك في منطقة الإدخال. يبدأ الفك تلقائيًا، وتظهر المعاينة مع أبعادها وحجم ملفها.</p>\n<p>راجع معاينة المربعات للشفافية، ثم اختر صيغة التنزيل: الأصلية للحفاظ على الملف الدقيق، أو PNG أو JPG أو WebP للتحويل. وإذا فشلت السلسلة، اقرأ رسالة الخطأ وراجع وجود اقتطاع أو بادئة مفقودة.</p>\n<p>للنسخة خطوة بخطوة، اقرأ <a href=\"/ar/blog/kayfiyya-tahwil-base64-ila-sura/\">كيف تحوّل Base64 إلى صورة</a>، ولمقارنة الأداء راجع <a href=\"/ar/blog/base64-vs-malafat-as-suwar/\">Base64 مقابل ملفات الصور: الأداء وحالات الاستخدام</a>. ولإنشاء سلسلة، استخدم <a href=\"/ar/tahwil-as-sura-ila-base64/\">مرمّز الصورة إلى Base64</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل يستطيع المفكك التعامل مع سلسلة Base64 ينقصها الحشو؟","answer":"يعتمد على مقدار النقص. السلسلة التي تنقصها علامات يساوي الأخيرة يمكن فكها أحيانًا، لأن المفكك يستدل على الحشو من الطول. أما السلسلة التي تنقصها أحرف بيانات حقيقية فلا يمكن إصلاحها."},{"question":"لماذا تبدو الصورة المفكوكة أصغر مما توقعت؟","answer":"الصورة المفكوكة تحمل أبعاد الملف الأصلي تمامًا، وقد تكون أصغر من الحجم الذي تخيلته. أيقونة 64 في 64 مفكوكة من سلسلة هي صورة صغيرة، وتنزيلها بصيغة أخرى لا يكبّرها."},{"question":"هل يمكنني فك عدة سلاسل Base64 دفعة واحدة؟","answer":"الأداة تفك سلسلة واحدة في كل مرة. الصق سلسلة ونزّل الصورة وامسح الإدخال ثم الصق التالية. زر المسح يزيل السلسلة الطويلة بسرعة لتنتقل إلى الصورة التالية."},{"question":"هل فك سلسلة Base64 وصلتني من غريب آمن؟","answer":"الفك نفسه آمن، لأن الأداة تحوّل النص فقط إلى ملف صورة محليًا في متصفحك. لا تفتح أو تشغّل أي ملف يأتي مع السلسلة، ولا تثق بمحتوى الصورة ثقة عمياء."},{"question":"ماذا أفعل إذا ظهرت الصورة المفكوكة بخلفية بيضاء بدل الشفافية؟","answer":"راجع معاينة المربعات أولًا. إذا أظهرت المعاينة شفافية، نزّل كأصلية أو PNG بدل JPG، لأن JPG يملأ المناطق الشفافة. وإذا أظهرت المعاينة أبيض أيضًا، فالملف الأصلي نفسه بلا شفافية."},{"question":"هل يمكنني فك سلسلة Base64 دون اتصال؟","answer":"نعم، بعد تحميل الصفحة. كل الفك يحدث في متصفحك دون أي خادم، فلا حاجة إلى اتصال بالإنترنت بعد التحميل الأولي. وهذا يجعل الأداة مفيدة في الطائرات والمكاتب الآمنة."}];
